input.command:
mkdir -p learn && cat > learn/runtime.js <<'JSEOF'
// The only file that knows how MLPL is reached from a page.
//
// Everything above this talks to `MlplRuntime`; everything below it is a
// bridge that will be deleted. See docs/mlpl-blockers.md B7.
//
// WHY A BRIDGE. The interpreter compiles to WASM and `mlpl-wasm` is already a
// clean cdylib exporting exactly what a lesson runner needs -- `WasmSession`
// with `new`, `eval` and `clear`. But the only PUBLISHED artifact is the whole
// Yew playground application, which mounts a UI on `init()` and hard-requires
// a Window. It cannot be loaded as a library.
//
// So the playground is loaded in a hidden iframe served from our own origin,
// and the parent reaches through: the playground's index.html assigns
// `window.wasmBindings`, and same-origin means we can read it. The UI it mounts
// is never shown. This costs an 8 MB download and an application nobody looks
// at; B7 asks for a headless `--target web` build of `mlpl-wasm` alone, and the
// step that adopts it replaces `IframeRuntime` and changes nothing else.

/**
 * How long to wait for the interpreter to publish its bindings, in ms.
 * Measured at ~100 ms locally and ~950 ms over the network from Pages.
 */
const BOOT_TIMEOUT_MS = 30000;

/**
 * An MLPL evaluation result.
 *
 * `display` is what the playground would print. `failed` is true when the
 * session could not evaluate the source at all.
 *
 * @typedef {{display: string, failed: boolean}} MlplResult
 */

/**
 * Strip the `Ok(...)` wrapper the session puts around a Result's payload.
 *
 * `to_json` answers a Result, and a session hands back that value's DISPLAY
 * form rather than the value, so JSON arrives as `Ok({"pass":1})` rather than
 * `{"pass":1}`. That is docs/upstream-asks.md #10 met at a second boundary,
 * recorded as #20. Unwrapping is one regex and it is the whole grading
 * boundary, so it lives here rather than in every checker.
 *
 * @param {string} display
 * @returns {string} the payload, or the input unchanged if it is not wrapped
 */
export function unwrapResult(display) {
  const m = /^(?:Ok|Err)\(([\s\S]*)\)$/.exec(display.trim());
  return m ? m[1] : display.trim();
}

/**
 * True when a session's output reports a failure to the reader.
 *
 * Two shapes, and the second is the one that hides. `include` and a syntax
 * error answer `error: ...`. But `write_text`, `read_text` and `run_script`
 * answer `Err(... no filesystem sandbox on this surface)` -- an ordinary
 * Result, invisible to anything that only looks for "error".
 *
 * @param {string} display
 * @returns {boolean}
 */
export function isFailure(display) {
  const o = display.trim();
  return /^error/i.test(o) || /^Err\(/.test(o);
}

/**
 * Drives MLPL through the playground bundle in a hidden same-origin iframe.
 *
 * TEMPORARY. Replaced wholesale when blocker B7 lands; nothing outside this
 * class knows the iframe exists.
 */
class IframeRuntime {
  /**
   * @param {string} bundleUrl path to the playground's index.html, same-origin
   */
  constructor(bundleUrl) {
    this.bundleUrl = bundleUrl;
    this.bindings = null;
    this.session = null;
    this.frame = null;
    this.preludes = [];
  }

  /** Boot the interpreter. Safe to await more than once. */
  async ready() {
    if (this.session) return;
    this.frame = document.createElement('iframe');
    this.frame.setAttribute('title', 'sw-MLPL interpreter');
    this.frame.hidden = true;
    this.frame.src = this.bundleUrl;
    document.body.appendChild(this.frame);

    const deadline = Date.now() + BOOT_TIMEOUT_MS;
    while (Date.now() < deadline) {
      const b = this.frame.contentWindow && this.frame.contentWindow.wasmBindings;
      if (b && b.WasmSession) {
        this.bindings = b;
        this.session = new b.WasmSession();
        return;
      }
      await new Promise(r => setTimeout(r, 50));
    }
    throw new Error('sw-MLPL did not start: no wasmBindings after ' + BOOT_TIMEOUT_MS + 'ms');
  }

  /**
   * Evaluate MLPL source in the session.
   * @param {string} source
   * @returns {MlplResult}
   */
  eval(source) {
    if (!this.session) throw new Error('runtime not ready');
    const display = this.session.eval(source);
    return { display, failed: isFailure(display) };
  }

  /**
   * Evaluate MLPL whose value is `to_json(...)` and parse the record.
   * @param {string} source
   * @returns {object}
   */
  evalJson(source) {
    const { display } = this.eval(source);
    const payload = unwrapResult(display);
    try {
      return JSON.parse(payload);
    } catch (e) {
      throw new Error('expected a JSON record, got: ' + display.slice(0, 200));
    }
  }

  /**
   * Load source that every later evaluation may rely on, and remember it.
   *
   * The browser session has no `include` (docs/upstream-asks.md #21), so a
   * library crosses as source text and has to be re-evaluated after a reset.
   * @param {string} source
   */
  prelude(source) {
    this.preludes.push(source);
    const { display, failed } = this.eval(source);
    if (failed) throw new Error('prelude failed: ' + display.slice(0, 200));
  }

  /** Drop the environment, then restore the preludes. */
  reset() {
    this.session.clear();
    const sources = this.preludes;
    this.preludes = [];
    sources.forEach(s => this.prelude(s));
  }
}

/**
 * Create the runtime this page should use.
 *
 * @param {string} bundleUrl same-origin path to the playground's index.html
 * @returns {IframeRuntime}
 */
export function createRuntime(bundleUrl) {
  return new IframeRuntime(bundleUrl);
}
JSEOF
echo "runtime.js written: $(wc -l < learn/runtime.js) lines"

cat > learn/spike/runtime-spike.html <<'HTMLEOF'
<!doctype html>
<meta charset="utf-8">
<title>Runtime spike — can a page drive sw-MLPL?</title>
<style>
  body { margin: 0; padding: 24px; background: #1a1b26; color: #c0caf5;
         font: 14px/1.55 ui-monospace, Menlo, monospace; }
  h1 { font-size: 18px; margin: 0 0 4px; }
  p.sub { color: #565f89; margin: 0 0 18px; max-width: 72ch; }
  .case { border: 1px solid #414868; border-radius: 6px; padding: 12px;
          margin-bottom: 10px; background: #1f2130; }
  .name { color: #e0af68; }
  .pass { color: #9ece6a; } .fail { color: #f7768e; }
  pre { margin: 6px 0 0; white-space: pre-wrap; }
  #verdict { font-size: 17px; margin-top: 18px; }
  a { color: #c0caf5; }
</style>

<h1>Runtime spike</h1>
<p class="sub">
  Evidence, not a demo. It asks whether this page can run the real sw-MLPL
  interpreter and have MLPL grade MLPL — the question the whole course rests
  on, because a course that graded with JavaScript would be teaching some other
  language. Everything below goes through
  <a href="../runtime.js"><code>learn/runtime.js</code></a>; this page does not
  know an iframe is involved. Saga A steps 1–2 of <code>docs/tutorial-plan.md</code>.
</p>

<div id="cases"></div>
<div id="verdict">booting the interpreter…</div>

<script type="module">
import { createRuntime, unwrapResult, isFailure } from '../runtime.js';

const casesEl = document.getElementById('cases');
const verdictEl = document.getElementById('verdict');
let failures = 0;

// Report one spike case, and count the failures.
function record(name, passed, detail) {
  failures += passed ? 0 : 1;
  const el = document.createElement('div');
  el.className = 'case';
  el.innerHTML =
    `<span class="name">${name}</span> ` +
    `<span class="${passed ? 'pass' : 'fail'}">${passed ? 'PASS' : 'FAIL'}</span>` +
    `<pre>${detail.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]))}</pre>`;
  casesEl.appendChild(el);
  console.log(`[spike] ${passed ? 'PASS' : 'FAIL'} ${name}: ${detail.split('\n')[0]}`);
}

// 0. The pure helpers, checked without booting anything.
record('the grading boundary unwraps a Result',
  unwrapResult('Ok({"pass":1})') === '{"pass":1}' && unwrapResult('7') === '7',
  'Ok({"pass":1}) -> {"pass":1}');
record('a failure is error: OR Err(',
  isFailure('error: nope') && isFailure('Err(no filesystem sandbox on this surface)') &&
  !isFailure('Ok(done)') && !isFailure('0 1 2'),
  'Err( counts -- write_text and run_script answer it instead of erroring');

const started = Date.now();
const mlpl = createRuntime('../mlpl/index.html');
try {
  await mlpl.ready();
} catch (e) {
  record('reach the interpreter from the parent page', false, String(e));
  verdictEl.innerHTML = '<span class="fail">SPIKE FAILED — the bridge does not work.</span>';
  throw e;
}
record('reach the interpreter from the parent page', true,
  `interpreter ready after ${Date.now() - started} ms`);

// 1. A multi-statement program with a def and a docstring -- the shape every
//    lesson's starter code has.
const defOut = mlpl.eval(
  'def u:f(x, y) {\n' +
  '  "Addition modulo three."\n' +
  '  mod(x + y, 3)\n' +
  '}\n' +
  'def u:plus(x, y) {\n' +
  '  "Ordinary addition -- escapes {0, 1, 2}."\n' +
  '  x + y\n' +
  '}\n' +
  'u:f(2, 2)'
).display;
record('def with a docstring, then call it', defOut.trim() === '1',
  `u:f(2, 2) => ${JSON.stringify(defOut)}`);

// 2. The session persists across evals, which is what lets a lesson preload a
//    library once and then run the learner's code against it.
const tableOut = mlpl.eval('t = table(:u:f, range(3), range(3))\nt').display;
record('session persists; table() builds the Cayley table',
  tableOut.includes('0 1 2') && tableOut.includes('1 2 0'),
  `t =>\n${tableOut}`);

// 3. to_json is the grading boundary.
const parsed = mlpl.evalJson('to_json({pass: 1, why: "closed", witness: {a: 0, b: 0}})');
record('to_json round-trips a grader record',
  parsed.pass === 1 && parsed.why === 'closed' && parsed.witness.a === 0,
  `parsed: ${JSON.stringify(parsed)}`);

// 4. The real library, loaded as a prelude -- proof it needs no rewrite.
const libSrc = await (await fetch('lib-algebra.mlpl')).text();
mlpl.prelude(libSrc);
const cls = mlpl.evalJson('to_json(u:classify(t))');
record('lib/algebra.mlpl loads into the session and classifies',
  cls.group === 1 && cls.abelian_group === 1,
  `${libSrc.split('\n').length} lines of library evaluated as source\n` +
  `u:classify(t) => ${JSON.stringify(cls)}`);

// 5. The grading shape of docs/tutorial-plan.md 4.1: a checker is an MLPL
//    expression answering {pass, why, witness}. Saga A step 3 moves it into
//    lib/grade.mlpl; the spike only proves it crosses.
mlpl.eval(
  'def u:grade_closed(t) {\n' +
  '  "Grade a table for closure, naming a witness when it escapes."\n' +
  '  inside = u:inside_mask(t)\n' +
  '  bad = argmax(flatten(1 - inside))\n' +
  '  {pass: u:is_closed(t), why: "every entry must name an element",\n' +
  '   witness: {a: floor(bad / u:order(t)), b: mod(bad, u:order(t))}}\n' +
  '}'
);
const good = mlpl.evalJson('to_json(u:grade_closed(t))');
const bad = mlpl.evalJson('e = table(:u:plus, range(3), range(3))\nto_json(u:grade_closed(e))');
record('an MLPL checker grades a good and a bad submission',
  good.pass === 1 && bad.pass === 0 && bad.witness.a === 1 && bad.witness.b === 2,
  `closed table   => ${JSON.stringify(good)}\n` +
  `escaping table => ${JSON.stringify(bad)}   (1 + 2 = 3 escapes {0,1,2})`);

// 6. Errors come back as values, so the runner can show the learner what went
//    wrong instead of dying.
const err = mlpl.eval('nope(');
record('a syntax error is reported, not thrown',
  err.failed && /error/i.test(err.display), JSON.stringify(err.display));

// 7. reset() drops the environment but restores the prelude, so one lesson
//    cannot leak into the next while the library stays available.
mlpl.reset();
const gone = mlpl.eval('t');
const libStillThere = mlpl.eval('u:order([[0, 1], [1, 0]])');
record('reset() clears the learner\'s work but keeps the library',
  gone.failed && !libStillThere.failed && libStillThere.display.trim() === '2',
  `t => ${JSON.stringify(gone.display)}\n` +
  `u:order(...) => ${JSON.stringify(libStillThere.display)}`);

verdictEl.innerHTML = failures === 0
  ? '<span class="pass">SPIKE PASSED — MLPL runs, and MLPL grades it.</span>'
  : `<span class="fail">SPIKE FAILED — ${failures} case(s) failed.</span>`;
console.log(`[spike] verdict: ${failures === 0 ? 'PASSED' : 'FAILED (' + failures + ')'}`);
</script>
HTMLEOF
python3 - <<'PYEOF'
p='scripts/build-site'
s=open(p).read()
old = """cp "$repo_root/learn/spike/runtime-spike.html" "$out/spike/index.html"
cp "$repo_root/lib/algebra.mlpl" "$out/spike/lib-algebra.mlpl\""""
new = """cp "$repo_root/learn/spike/runtime-spike.html" "$out/spike/index.html"
cp "$repo_root/lib/algebra.mlpl" "$out/spike/lib-algebra.mlpl"

# The runtime interface, one level up from the pages that import it. Every
# page reaches MLPL through this and none of them knows how. See B7.
cp "$repo_root/learn/runtime.js" "$out/runtime.js\""""
assert old in s
open(p,'w').write(s.replace(old,new))
print('build-site ships runtime.js')
